SELECT s.id, s.category_id AS categoryId, s.name, s.price, s.status, s.description, s.image, s.update_time AS updateTime, c.name AS categoryName FROM setmeal s LEFT JOIN category c ON s.category_id = c.id
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.category_id = #{categoryId}
AND s.status = #{status}
ORDER BY s.create_time DESC

